// Flow 3 · compute metrics (Run Once for All Items)
// Reads the four tabs and returns one item with aggregates only: no finding ids, file
// paths, reasons or reviewer names leave this node, so the output is safe to publish.
// Every rate is null when its denominator is 0, so an empty sheet never divides by zero.

const rowsOf = (node, key) => {
  try { return $(node).all().map((i) => i.json).filter((r) => String(r[key] ?? '') !== ''); }
  catch (e) { return []; }
};
const num = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
const rate = (a, b) => (b ? Math.round((a / b) * 1000) / 1000 : null);
const round2 = (v) => Math.round(v * 100) / 100;
const countBy = (rows, fn) => {
  const out = {};
  for (const r of rows) { const k = String(fn(r) ?? '') || '(none)'; out[k] = (out[k] ?? 0) + 1; }
  return Object.fromEntries(Object.entries(out).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])));
};
// Nearest-rank percentile on a sorted copy.
const pct = (values, p) => {
  if (!values.length) return null;
  const s = [...values].sort((a, b) => a - b);
  return s[Math.min(s.length - 1, Math.max(0, Math.ceil((p / 100) * s.length) - 1))];
};

const findings = rowsOf('Get findings', 'id');
const occurrences = rowsOf('Get occurrences', 'finding_id');
const log = rowsOf('Get decisions_log', 'finding_id');
const runRows = rowsOf('Get runs', 'run_id');

// A re-run of the same workflow run posts the same run_id again: count it once.
const runsById = new Map();
for (const r of runRows) if (!runsById.has(String(r.run_id))) runsById.set(String(r.run_id), r);
const runs = [...runsById.values()];
const sum = (rows, col) => rows.reduce((t, r) => t + num(r[col]), 0);

// Volume and deduplication.
const rawRecords = sum(runs, 'raw_records');
const sightings = sum(runs, 'unique_findings');
const volume = {
  runs: runs.length,
  prs: new Set(runs.map((r) => String(r.pr))).size,
  runs_without_findings: runs.filter((r) => num(r.unique_findings) === 0).length,
  emails_sent: runs.filter((r) => String(r.email_sent).toLowerCase() === 'true').length,
  raw_records: rawRecords,
  sightings,
  unique_findings: findings.length,
  review_locations: new Set(findings.map((f) => String(f.group_key || `${f.file}:${f.line}`))).size,
};
const dedup = {
  duplicates_within_runs: sum(runs, 'duplicates'),
  repeat_sightings: sum(runs, 'known_findings'),
  reviews_without_dedup: rawRecords,
  reviews_with_dedup: findings.length,
  reviews_saved: Math.max(0, rawRecords - findings.length),
  saved_rate: rate(Math.max(0, rawRecords - findings.length), rawRecords),
};

// Human decisions (the findings row holds the latest one).
const decided = findings.filter((f) => String(f.status) === 'decided');
const open = findings.filter((f) => String(f.status) !== 'decided');
const disp = (f) => String(f.disposition ?? '');
const accepted = decided.filter((f) => disp(f) === 'accepted');
const falsePos = decided.filter((f) => disp(f) === 'false_positive');
const logCount = new Map();
for (const l of log) logCount.set(String(l.finding_id), (logCount.get(String(l.finding_id)) ?? 0) + 1);
const decisions = {
  decided: decided.length,
  open: open.length,
  by_disposition: countBy(decided, disp),
  open_by_disposition: countBy(open, disp),
  actionable_rate: rate(accepted.length, decided.length),
  false_positive_rate: rate(falsePos.length, decided.length),
  false_positives_in_impossible_level: falsePos.filter((f) => String(f.dvwa_level) === 'impossible').length,
  findings_in_impossible_level: findings.filter((f) => String(f.dvwa_level) === 'impossible').length,
  log_entries: log.length,
  log_by_source: countBy(log, (l) => l.source),
  findings_decided_more_than_once: [...logCount.values()].filter((n) => n > 1).length,
  // A rationale under 20 characters is a sign of rubber-stamping, not review.
  short_rationales: decided.filter((f) => String(f.reason ?? '').trim().length < 20).length,
  short_rationale_rate: rate(decided.filter((f) => String(f.reason ?? '').trim().length < 20).length, decided.length),
};

const hours = decided.map((f) => Number(f.time_to_decision_h)).filter((h) => Number.isFinite(h) && h >= 0);
const timeToDecision = {
  measured: hours.length,
  median_h: hours.length ? round2(pct(hours, 50)) : null,
  p90_h: hours.length ? round2(pct(hours, 90)) : null,
  max_h: hours.length ? round2(Math.max(...hours)) : null,
};

// AI reliability. Secrets are never sent to the AI, so they are not part of the base.
const eligible = findings.filter((f) => String(f.category) !== 'secrets' && String(f.tool) !== 'gitleaks');
const provider = (f) => String(f.ai_provider || 'none');
const answered = eligible.filter((f) => provider(f) !== 'none');
const gaps = (f) => String(f.ai_proof_gaps ?? '').split('|').map((g) => g.trim()).filter(Boolean).length;
const ai = {
  eligible: eligible.length,
  not_sent_secrets: findings.length - eligible.length,
  by_provider: countBy(eligible, provider),
  by_status: countBy(answered, (f) => f.ai_status),
  fallback_rate: rate(eligible.filter((f) => provider(f) === 'groq').length, eligible.length),
  failure_rate: rate(eligible.length - answered.length, eligible.length),
  failures_logged_in_runs: sum(runs, 'ai_failures'),
  injection_suspected: answered.filter((f) => String(f.ai_reason ?? '').startsWith('[injection suspected')).length,
  avg_proof_gaps: answered.length ? round2(answered.reduce((t, f) => t + gaps(f), 0) / answered.length) : null,
};

// AI vs human, only where both gave an answer. Agreement is not accuracy: it also rises
// when the reviewer simply follows the suggestion (see short_rationale_rate).
const SEV = ['info', 'low', 'medium', 'high', 'critical'];
const both = decided.filter((f) => provider(f) !== 'none' && String(f.category) !== 'secrets');
const humanReal = (f) => ['accepted', 'suppressed'].includes(disp(f));
const verdictPairs = both.filter((f) => ['candidate', 'likely_false_positive'].includes(String(f.ai_status)));
const verdictAgree = verdictPairs.filter((f) => (String(f.ai_status) === 'candidate') === humanReal(f));
const sevPairs = both.filter((f) => SEV.includes(String(f.ai_severity)) && SEV.includes(String(f.final_severity)));
const sevDiff = sevPairs.map((f) => SEV.indexOf(String(f.final_severity)) - SEV.indexOf(String(f.ai_severity)));
const agreement = {
  compared: both.length,
  ai_abstained_needs_evidence: both.filter((f) => String(f.ai_status) === 'needs_evidence').length,
  verdict_compared: verdictPairs.length,
  verdict_agreement_rate: rate(verdictAgree.length, verdictPairs.length),
  ai_real_human_real: verdictPairs.filter((f) => String(f.ai_status) === 'candidate' && humanReal(f)).length,
  ai_real_human_false_positive: verdictPairs.filter((f) => String(f.ai_status) === 'candidate' && !humanReal(f)).length,
  ai_false_positive_human_real: verdictPairs.filter((f) => String(f.ai_status) !== 'candidate' && humanReal(f)).length,
  ai_false_positive_human_false_positive: verdictPairs.filter((f) => String(f.ai_status) !== 'candidate' && !humanReal(f)).length,
  severity_compared: sevPairs.length,
  severity_exact_rate: rate(sevDiff.filter((d) => d === 0).length, sevPairs.length),
  severity_within_one_rate: rate(sevDiff.filter((d) => Math.abs(d) <= 1).length, sevPairs.length),
  human_raised_severity: sevDiff.filter((d) => d > 0).length,
  human_lowered_severity: sevDiff.filter((d) => d < 0).length,
};

const proofGaps = {
  open_findings_with_gaps: open.filter((f) => gaps(f) > 0).length,
  open_gaps: open.reduce((t, f) => t + gaps(f), 0),
};

const distributions = {
  tool: countBy(findings, (f) => f.tool),
  category: countBy(findings, (f) => f.category),
  scanner_severity: countBy(findings, (f) => f.severity),
  final_severity: countBy(decided, (f) => f.final_severity),
  module: countBy(findings, (f) => f.module),
  dvwa_level: countBy(findings, (f) => f.dvwa_level),
  origin: countBy(findings, (f) => f.origin),
};

const received = runs.map((r) => String(r.received_at ?? '')).filter(Boolean).sort();
return [{ json: {
  schema_version: '1.0',
  generated_at: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
  window: { first_run: received[0] ?? null, last_run: received[received.length - 1] ?? null },
  volume,
  dedup,
  decisions,
  time_to_decision: timeToDecision,
  ai,
  agreement,
  proof_gaps: proofGaps,
  distributions,
  data_quality: {
    duplicate_run_rows_ignored: runRows.length - runs.length,
    occurrence_rows: occurrences.length,
    occurrences_match_sightings: occurrences.length === sightings,
  },
} }];

// Flow 3 · build readout (Run Once for All Items)
// Turns the metrics into the executive readout: scope · evidence · decision · value signal ·
// next action · owner · time · proof gaps. Every sentence is derived from the numbers; the
// readout points to the record (the Sheet), it does not replace it.
// Distribution keys (module, tool) come from file paths a PR author controls, so every
// value is HTML-escaped.

const OWNER = 'Repository owner (human reviewer)';
const REPO = 'moypulido/dvwa-ai-triage';
const SHEET_URL = 'https://docs.google.com/spreadsheets/d/YOUR_SHEET_ID/edit';

const m = $input.first().json;
const { volume: v, dedup: d, decisions: dec, time_to_decision: t, ai, agreement: ag, proof_gaps: pg,
  distributions: dist } = m;

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => (
  { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const pc = (r) => (r === null || r === undefined ? 'n/a' : `${Math.round(r * 1000) / 10}%`);
const dur = (h) => (h === null || h === undefined ? 'n/a' : h < 1 ? `${Math.round(h * 60)} min` : `${h} h`);
const plural = (n, one, many) => `${n} ${n === 1 ? one : many ?? `${one}s`}`;
const list = (o) => Object.entries(o ?? {}).map(([k, n]) => `${k} ${n}`).join(', ') || 'none';
const day = (iso) => String(iso ?? '').slice(0, 16).replace('T', ' ');

const accepted = dec.by_disposition?.accepted ?? 0;
const falsePos = dec.by_disposition?.false_positive ?? 0;
const urgent = (dist.final_severity?.critical ?? 0) + (dist.final_severity?.high ?? 0);

// Next actions, most important first. Each one is triggered by a number, never by opinion.
const actions = [];
if (dec.open > 0) actions.push(`Decide the ${plural(dec.open, 'open finding')} (${list(dec.open_by_disposition)}).`);
if (ag.ai_false_positive_human_real > 0) {
  actions.push(`Re-check ${plural(ag.ai_false_positive_human_real, 'finding')} the AI marked as likely false positive and the reviewer accepted.`);
}
if (dec.findings_in_impossible_level > 0 && dec.false_positives_in_impossible_level === 0) {
  actions.push(`Re-check the ${plural(dec.findings_in_impossible_level, 'finding')} in impossible-level files: that level validates its input, and none was marked false positive.`);
}
if (dec.short_rationale_rate !== null && dec.short_rationale_rate >= 0.5) {
  actions.push(`Raise review quality: ${dec.short_rationales} of ${dec.decided} decisions have a rationale under 20 characters. Cite the lines checked.`);
}
if (ai.failure_rate > 0) actions.push(`Look at AI failures: ${pc(ai.failure_rate)} of eligible findings got no suggestion.`);
if (ai.injection_suspected > 0) actions.push(`Review ${plural(ai.injection_suspected, 'finding')} with a suspected prompt injection.`);
if (accepted > 0) actions.push(`Track the ${plural(accepted, 'accepted finding')} to a fix or a documented exception (${urgent} critical or high).`);
if (!actions.length) actions.push('No action needed.');

const sections = [
  ['Scope', [
    `Repository ${REPO}: ${plural(v.runs, 'scan run')} across ${plural(v.prs, 'pull request')}, ${day(m.window.first_run)} to ${day(m.window.last_run)} UTC.`,
    `${plural(v.runs_without_findings, 'run')} had nothing in scope. Modules seen: ${list(dist.module)}.`,
    'Static analysis only (semgrep, gitleaks, trivy). The app is never deployed or run.',
  ]],
  ['Evidence', [
    `${plural(v.raw_records, 'scanner record')} → ${plural(v.unique_findings, 'unique finding')} at ${plural(v.review_locations, 'code location')}.`,
    `By tool: ${list(dist.tool)}. By scanner severity: ${list(dist.scanner_severity)}. Origin: ${list(dist.origin)}.`,
    `AI suggestions: ${ai.eligible} eligible (${list(ai.by_provider)}); ${ai.not_sent_secrets} secrets never sent. Fallback used on ${pc(ai.fallback_rate)}, failures ${pc(ai.failure_rate)}, suspected injections ${ai.injection_suspected}.`,
    'Every item is a candidate, not a confirmed vulnerability.',
  ]],
  ['Decision', [
    `${dec.decided} decided, ${dec.open} open. Dispositions: ${list(dec.by_disposition)}.`,
    `Actionable rate ${pc(dec.actionable_rate)} (accepted ÷ decided). False positives ${falsePos} (${pc(dec.false_positive_rate)}), ${dec.false_positives_in_impossible_level} of them in impossible-level files.`,
    `AI vs human on ${ag.verdict_compared} findings: same verdict ${pc(ag.verdict_agreement_rate)}, same severity ${pc(ag.severity_exact_rate)} (human raised ${ag.human_raised_severity}, lowered ${ag.human_lowered_severity}).`,
    'A human made every decision; the AI only suggests. Agreement is not accuracy: it also rises when the reviewer follows the suggestion.',
  ]],
  ['Value signal', [
    `Deduplication: ${d.reviews_saved} of ${d.reviews_without_dedup} reviews avoided (${pc(d.saved_rate)}). ${d.repeat_sightings} repeat sightings and ${d.duplicates_within_runs} in-run duplicates needed no new decision.`,
    `${plural(v.emails_sent, 'email')} for ${plural(v.runs, 'run')}: runs with nothing new to decide stay silent.`,
  ]],
  ['Next action', actions],
  ['Owner', [OWNER]],
  ['Time', [
    `Time to decision: median ${dur(t.median_h)}, p90 ${dur(t.p90_h)}, max ${dur(t.max_h)} (${t.measured} decisions).`,
    `Readout generated ${day(m.generated_at)} UTC.`,
  ]],
  ['Proof gaps', [
    `Open: ${plural(pg.open_gaps, 'proof gap')} on ${plural(pg.open_findings_with_gaps, 'undecided finding')}. The AI listed ${ai.avg_proof_gaps ?? 'n/a'} gaps per finding on average.`,
    'No runtime validation: nothing here is confirmed exploitable.',
    'These scanners do not detect logic flaws such as broken access control; a clean scan is not proof of safety.',
  ]],
];

const subject = `[dvwa-ai-triage] Readout: ${plural(v.unique_findings, 'finding')}, ${accepted} accepted, ${dec.open} open (${plural(v.runs, 'run')})`;

const text = [
  ...sections.map(([title, lines]) => [title.toUpperCase(), ...lines.map((l) => `- ${l}`)].join('\n')),
  `Records: ${SHEET_URL}`,
].join('\n\n');

const th = 'style="text-align:left;vertical-align:top;padding:8px 12px 8px 0;border-bottom:1px solid #ddd;white-space:nowrap"';
const td = 'style="padding:8px 0;border-bottom:1px solid #ddd"';
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#222;max-width:720px">
<p><b>Executive readout</b> · ${esc(REPO)}</p>
<table style="border-collapse:collapse;width:100%">${sections.map(([title, lines]) =>
  `<tr><th ${th}>${esc(title)}</th><td ${td}>${lines.map((l) => esc(l)).join('<br>')}</td></tr>`).join('')}</table>
<p><a href="${esc(SHEET_URL)}">Records</a> (the readout points to the record; it does not replace it)</p>
</div>`;

return [{ json: { _subject: subject, _text: text, _html: html, metrics: m } }];
